    if (library == null || bookTitle == null || bookTitle.trim().isEmpty())
    {
      return false;
    }

    Document matchedDocument = null;
    for (Document document : library.getDocuments())
    {
      if (bookTitle.equals(document.getTitle()))
      {
        matchedDocument = document;
        break;
      }
    }

    if (!(matchedDocument instanceof Book))
    {
      return false;
    }

    Book book = (Book)matchedDocument;

    for (Member member : library.getMembers())
    {
      for (BorrowRecord borrowRecord : member.getBorrowRecords())
      {
        if (borrowRecord.getBook() == book)
        {
          return false;
        }
      }
    }

    int activeCount = 0;
    for (BorrowRecord borrowRecord : getBorrowRecords())
    {
      if (borrowRecord.getBook() != null)
      {
        activeCount++;
      }
    }

    if (activeCount >= 3)
    {
      return false;
    }

    BorrowRecord newBorrowRecord = MunicipalLibraryFactory.eINSTANCE.createBorrowRecord();
    newBorrowRecord.setBorrowingDate(today);
    newBorrowRecord.setReturnDue(new Date(today.getTime() + 7L * 24L * 60L * 60L * 1000L));
    newBorrowRecord.setBook(book);
    getBorrowRecords().add(newBorrowRecord);
    return true;
